  KEY `orders_order_group_id_foreign` (`order_group_id`) USING BTREE,
  KEY `orders_shop_id_foreign` (`shop_id`) USING BTREE,
  KEY `orders_logistic_id_foreign` (`logistic_id`) USING BTREE,
