  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `shop_id` int(11) NOT NULL,
  `demanded_amount` double NOT NULL DEFAULT 0,
  `additional_info` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `given_amount` double NOT NULL DEFAULT 0,
  `document_of_proof` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `transaction_details` longtext COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `transaction_via` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'gateway name',
  `transaction_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payment_status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT 'pending/review/successful/cancelled',
  `reason_for_cancellation` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

