INSERT INTO `product_localizations` (`id`, `product_id`, `name`, `short_description`, `description`, `lang_key`, `created_at`, `updated_at`, `deleted_at`) VALUES (2, 1, 'देशी शोशा (स्थानीय ककड़ी) देशी शोशा ± 25 ग्राम', 'प्रत्येक 500 ग्राम उत्पाद में शोशा (स्थानीय ककड़ी) के 3-5 पीसी होंगे।\r\n\r\nस्थानीय रूप से स्रोत। कुछ खाद्य पदार्थ खीरे की तरह ठंडे होते हैं। जबकि ज्यादातर लोग खीरे को सब्जियों के रूप में सोचते हैं, वे वास्तव में एक फल हैं। खीरे स्वाभाविक रूप से कैलोरी, कार्बोहाइड्रेट, सोडियम, वसा और कोलेस्ट्रॉल और हाइड्रेटिंग गुणों में कम होते हैं।', '<p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p8223.0.6.0.1.0.1.4.$line-0\" style=\"box-sizing: border-box; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; -webkit-tap-highlight-color: transparent; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font style=\"vertical-align: inherit;\">प्रत्येक 500 ग्राम उत्पाद में शोशा (स्थानीय ककड़ी) के 3-5 पीसी होंगे।</font></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p8223.0.6.0.1.0.1.4.$line-0\" style=\"box-sizing: border-box; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; -webkit-tap-highlight-color: transparent; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><br></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p8223.0.6.0.1.0.1.4.$line-1\" style=\"box-sizing: border-box; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; -webkit-tap-highlight-color: transparent; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p8223.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; -webkit-tap-highlight-color: transparent; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font style=\"vertical-align: inherit;\">स्थानीय रूप से स्रोत। कुछ खाद्य पदार्थ खीरे की तरह ठंडे होते हैं। जबकि ज्यादातर लोग खीरे को सब्जियों के रूप में सोचते हैं, वे वास्तव में एक फल हैं। खीरे स्वाभाविक रूप से कैलोरी, कार्बोहाइड्रेट, सोडियम, वसा और कोलेस्ट्रॉल और हाइड्रेटिंग गुणों में कम होते हैं।</font></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p8223.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; -webkit-tap-highlight-color: transparent; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><br></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p8223.0.6.0.1.0.1.4.$line-0\" style=\"box-sizing: border-box; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; -webkit-tap-highlight-color: transparent; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font style=\"vertical-align: inherit;\">प्रत्येक 500 ग्राम उत्पाद में शोशा (स्थानीय ककड़ी) के 3-5 पीसी होंगे।</font></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p8223.0.6.0.1.0.1.4.$line-1\" style=\"box-sizing: border-box; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; -webkit-tap-highlight-color: transparent; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p8223.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; -webkit-tap-highlight-color: transparent; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font style=\"vertical-align: inherit;\">स्थानीय रूप से स्रोत। कुछ खाद्य पदार्थ खीरे की तरह ठंडे होते हैं। जबकि ज्यादातर लोग खीरे को सब्जियों के रूप में सोचते हैं, वे वास्तव में एक फल हैं। खीरे स्वाभाविक रूप से कैलोरी, कार्बोहाइड्रेट, सोडियम, वसा और कोलेस्ट्रॉल और हाइड्रेटिंग गुणों में कम होते हैं।</font></p>', 'hi', '2023-03-12 22:41:21', '2023-03-12 22:44:51', NULL);
INSERT INTO `product_localizations` (`id`, `product_id`, `name`, `short_description`, `description`, `lang_key`, `created_at`, `updated_at`, `deleted_at`) VALUES (3, 2, 'Agro Acres Pistachio (Pesta Badam)', NULL, '<p><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Pistachios provide Vitamin A and C which are not found in significant amounts in almonds. Pistachios provide 4% of the daily recommended amount of calcium while almonds provide 10%. Pistachios provide 8% of the daily value of iron while almonds provide 6%.</span></p><p><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Pistachios provide Vitamin A and C which are not found in significant amounts in almonds. Pistachios provide 4% of the daily recommended amount of calcium while almonds provide 10%. Pistachios provide 8% of the daily value of iron while almonds provide 6%.</span><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><br></span><br></p>', 'en', '2023-03-12 22:51:54', '2023-03-12 22:51:54', NULL);
INSERT INTO `product_localizations` (`id`, `product_id`, `name`, `short_description`, `description`, `lang_key`, `created_at`, `updated_at`, `deleted_at`) VALUES (4, 3, 'Badhakopi (Cabbage)', NULL, '<p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p5935.0.6.0.1.0.1.4.$line-0\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Weight: 1.5-1.8 kg</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p5935.0.6.0.1.0.1.4.$line-1\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p5935.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Cabbage structurally consists of clusters of stiff leaves superimposed in compact layers, allowing it to aquire round or globular shape vegetable. Fresh cabbage is an excellent source of natural antioxidant, vitamin C. Provides 36.6 mg or about 61% of RDA per 100 g. Regular consumption of foods rich in vitamin C helps the body develop resistance against infectious agents and scavenge harmful, pro-inflammatory free radicals. Cabbage is one of storehouse of phyto-chemicals like thiocyanates, indole-3-carbinol, lutein, zea-xanthin, sulforaphane, and isothiocyanates. These compounds work as powerful antioxidants and known to help protect against breast, colon, and prostate cancers.</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p5935.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><br></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p5935.0.6.0.1.0.1.4.$line-0\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Weight: 1.5-1.8 kg</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p5935.0.6.0.1.0.1.4.$line-1\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p5935.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Cabbage structurally consists of clusters of stiff leaves superimposed in compact layers, allowing it to aquire round or globular shape vegetable. Fresh cabbage is an excellent source of natural antioxidant, vitamin C. Provides 36.6 mg or about 61% of RDA per 100 g. Regular consumption of foods rich in vitamin C helps the body develop resistance against infectious agents and scavenge harmful, pro-inflammatory free radicals. Cabbage is one of storehouse of phyto-chemicals like thiocyanates, indole-3-carbinol, lutein, zea-xanthin, sulforaphane, and isothiocyanates. These compounds work as powerful antioxidants and known to help protect against breast, colon, and prostate cancers.</p>', 'en', '2023-03-12 23:00:38', '2023-03-12 23:00:38', NULL);
INSERT INTO `product_localizations` (`id`, `product_id`, `name`, `short_description`, `description`, `lang_key`, `created_at`, `updated_at`, `deleted_at`) VALUES (5, 4, 'Guava Premium (± 50 gm)', NULL, '<p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6024.0.6.0.1.0.1.4.$line-0\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">3pcs -4pcs</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6024.0.6.0.1.0.1.4.$line-1\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6024.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Every 1 kg of the product will contain 3pcs-4pcs of Guava.</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6024.0.6.0.1.0.1.4.$line-3\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6024.0.6.0.1.0.1.4.$line-4\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Guava is a tropical fruit rich in high-profile nutrients. Thai guavas are generally the size of a softball with apple green skin that can range from bumpy to smooth. The flesh is white with pale yellow seeds and tends to be drier than the pink type of guavas. Thai guavas are only mildly sweet and have very little fragrance. The crunchy flesh and hard seeds are both edible. Guavas come in two broad groups divided by the color of their flesh: pink and white. Thai guavas are a group of guavas within the white category that include a number of varieties. Thai Guava Guava is very helpful for those who want to lose weight without compromising their intake of proteins, vitamins and fiber. Guava is very high in roughage and rich in vitamins, proteins and minerals Adding a medium-sized guava to your lunch and you will not feel hungry again until the evening.</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6024.0.6.0.1.0.1.4.$line-4\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><br></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6024.0.6.0.1.0.1.4.$line-0\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">3pcs -4pcs</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6024.0.6.0.1.0.1.4.$line-1\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6024.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Every 1 kg of the product will contain 3pcs-4pcs of Guava.</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6024.0.6.0.1.0.1.4.$line-3\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6024.0.6.0.1.0.1.4.$line-4\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Guava is a tropical fruit rich in high-profile nutrients. Thai guavas are generally the size of a softball with apple green skin that can range from bumpy to smooth. The flesh is white with pale yellow seeds and tends to be drier than the pink type of guavas. Thai guavas are only mildly sweet and have very little fragrance. The crunchy flesh and hard seeds are both edible. Guavas come in two broad groups divided by the color of their flesh: pink and white. Thai guavas are a group of guavas within the white category that include a number of varieties. Thai Guava Guava is very helpful for those who want to lose weight without compromising their intake of proteins, vitamins and fiber. Guava is very high in roughage and rich in vitamins, proteins and minerals Adding a medium-sized guava to your lunch and you will not feel hungry again until the evening.</p>', 'en', '2023-03-12 23:05:58', '2023-03-12 23:05:58', NULL);
INSERT INTO `product_localizations` (`id`, `product_id`, `name`, `short_description`, `description`, `lang_key`, `created_at`, `updated_at`, `deleted_at`) VALUES (6, 5, 'Broccoli', '800gm - 1.5 kg\r\n\r\nWhen it comes to great-tasting nutrition, broccoli is an all-star food with many health benefits. While low in calories, broccoli is rich in essential vitamins and minerals, in addition to fiber.', '<p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-0\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">800gm - 1.5 kg</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-1\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">When it comes to great-tasting nutrition, broccoli is an all-star food with many health benefits. While low in calories, broccoli is rich in essential vitamins and minerals, in addition to fiber.</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-3\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-4\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Broccoli belongs to a family of vegetables called cruciferous vegetables and its close relatives include brussel sprouts, cauliflower, and cabbage. Broccoli contains sulforophane, a sulfur-containing compound present in cruciferous vegetables. Researchers are studying the anti-cancer properties of sulforophane and have come to some interesting conclusions, although more research is needed.</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-5\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-6\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">As if that\'s not enough, a cup of cooked broccoli offers as much vitamin C as an orange, and is a good source of beta-carotene. Broccoli contains vitamins B1, B2, B3, B6, iron, magnesium, potassium, and zinc too. It also provides fiber and is low in calories.</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-7\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-8\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Nutritional facts/Ingredients :</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-9\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Broccoli Nutrients</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-10\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Broccoli is a great source of vitamins K and C, a good source of folate (folic acid) and also provides potassium, fiber.</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-11\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-12\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Vitamin K – essential for the functioning of many proteins involved in blood clotting</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-13\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-14\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Vitamin C – builds collagen, which forms body tissue and bone, and helps cuts and wounds heal. Vitamin C is a powerful antioxidant and protects the body from damaging free radicals.</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-15\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-16\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Fiber – diets high in fiber promote digestive health. A high fiber intake can also help lower cholesterol.</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-17\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-18\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Potassium – a mineral and electrolyte that is essential for the function of nerves and heart contraction.</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-19\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-20\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Folate – is necessary for the production and maintenance of new cells in the body.</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p17022.0.6.0.1.0.1.4.$line-20\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><br></p>', 'en', '2023-03-12 23:08:14', '2023-03-12 23:17:27', NULL);
INSERT INTO `product_localizations` (`id`, `product_id`, `name`, `short_description`, `description`, `lang_key`, `created_at`, `updated_at`, `deleted_at`) VALUES (7, 6, 'Green Melon ± 50 gm', NULL, '<p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6008.0.6.0.1.0.1.4.$line-0\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">9pcs -10pcs</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6008.0.6.0.1.0.1.4.$line-1\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6008.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Green apples provide a huge range of health and beauty benefits, especially when compared to red apples. Green apple has some sweet and sour variety and amazing taste. Green apples possess glossy skin, along with a juicy flesh. They\'re high in fiber and help keep the digestive tract clean and healthy. Green apples are energy givers, contain both flavonoid and polyphenol, also can help prevent diarrhea. One of the major green apple benefits is the high fiber content. These high levels of fiber can help to reduce cholesterol. Green apple decreases chance of colon cancer. A 1-cup serving of green apple juice has 253 calories, with less than 1 gram of total fat. It also has 1.92 grams of protein and almost 42 grams of sugar. Because of this, a single serving of green apple juice has over 59 grams of carbohydrates.</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6008.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><br></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6008.0.6.0.1.0.1.4.$line-0\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">9pcs -10pcs</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6008.0.6.0.1.0.1.4.$line-1\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6008.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Green apples provide a huge range of health and beauty benefits, especially when compared to red apples. Green apple has some sweet and sour variety and amazing taste. Green apples possess glossy skin, along with a juicy flesh. They\'re high in fiber and help keep the digestive tract clean and healthy. Green apples are energy givers, contain both flavonoid and polyphenol, also can help prevent diarrhea. One of the major green apple benefits is the high fiber content. These high levels of fiber can help to reduce cholesterol. Green apple decreases chance of colon cancer. A 1-cup serving of green apple juice has 253 calories, with less than 1 gram of total fat. It also has 1.92 grams of protein and almost 42 grams of sugar. Because of this, a single serving of green apple juice has over 59 grams of carbohydrates.</p>', 'en', '2023-03-12 23:12:33', '2023-03-12 23:12:33', NULL);
INSERT INTO `product_localizations` (`id`, `product_id`, `name`, `short_description`, `description`, `lang_key`, `created_at`, `updated_at`, `deleted_at`) VALUES (8, 7, 'Cantaloupe Melon', NULL, '<h2 style=\"box-sizing: border-box; outline: none; margin-right: 0px; margin-bottom: 2px; margin-left: 0px; padding: 0px; cursor: default; line-height: 18px; overflow: hidden; text-overflow: inherit; overflow-wrap: break-word;\"><font color=\"#222222\" face=\"Roboto, sans-serif\"><span style=\"font-size: 14px; font-weight: 400;\">Beautiful tasty sliced juicy cantaloupe melon, muskmelon, rock melon isolated on white background, close up, clipping path, cut out.</span></font></h2><h2 style=\"box-sizing: border-box; outline: none; margin-right: 0px; margin-bottom: 2px; margin-left: 0px; padding: 0px; cursor: default; line-height: 18px; overflow: hidden; text-overflow: inherit; overflow-wrap: break-word;\"><font color=\"#222222\" face=\"Roboto, sans-serif\"><span style=\"font-size: 14px; font-weight: 400;\">Beautiful tasty sliced juicy cantaloupe melon, muskmelon, rock melon isolated on white background, close up, clipping path, cut out</span><br></font><br></h2>', 'en', '2023-03-12 23:15:52', '2023-03-12 23:15:52', NULL);
INSERT INTO `product_localizations` (`id`, `product_id`, `name`, `short_description`, `description`, `lang_key`, `created_at`, `updated_at`, `deleted_at`) VALUES (9, 8, 'Red Tomato ± 25 gm', NULL, '<p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6302.0.6.0.1.0.1.4.$line-0\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Every 500 gm of the product will contain 7-10 pcs of Tomato.</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6302.0.6.0.1.0.1.4.$line-1\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6302.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">The tomato is consumed in diverse ways, including raw, as an ingredient in many dishes, sauces, salads, and drinks. While it is botanically a fruit, it is considered a vegetable for culinary purposes. The fruit is rich in lycopene, which may have beneficial health effects.</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6302.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><br></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6302.0.6.0.1.0.1.4.$line-0\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Every 500 gm of the product will contain 7-10 pcs of Tomato.</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6302.0.6.0.1.0.1.4.$line-1\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6302.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">The tomato is consumed in diverse ways, including raw, as an ingredient in many dishes, sauces, salads, and drinks. While it is botanically a fruit, it is considered a vegetable for culinary purposes. The fruit is rich in lycopene, which may have beneficial health effects.</p>', 'en', '2023-03-12 23:51:01', '2023-03-12 23:51:01', NULL);
INSERT INTO `product_localizations` (`id`, `product_id`, `name`, `short_description`, `description`, `lang_key`, `created_at`, `updated_at`, `deleted_at`) VALUES (10, 9, 'Red Capsicum ±12 gm', NULL, '<p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p10226.0.6.0.1.0.1.4.$line-0\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">2 pcs</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p10226.0.6.0.1.0.1.4.$line-1\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p10226.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">A wonderful combination of tangy taste and crunchy texture, sweet Capsicum are the ornaments of the vegetable world with their beautifully shaped glossy exterior that comes in a wide array of vivid colors ranging from red. Capsicum is not only an excellent source of carotenoids, but also a source of over 30 different members of the carotenoid nutrient family.It also contains vitamin C and E.</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p10226.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><br></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p10226.0.6.0.1.0.1.4.$line-0\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">2 pcs</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p10226.0.6.0.1.0.1.4.$line-1\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p10226.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">A wonderful combination of tangy taste and crunchy texture, sweet Capsicum are the ornaments of the vegetable world with their beautifully shaped glossy exterior that comes in a wide array of vivid colors ranging from red. Capsicum is not only an excellent source of carotenoids, but also a source of over 30 different members of the carotenoid nutrient family.It also contains vitamin C and E.</p>', 'en', '2023-03-12 23:56:52', '2023-03-12 23:56:52', NULL);
