INSERT INTO `product_localizations` (`id`, `product_id`, `name`, `short_description`, `description`, `lang_key`, `created_at`, `updated_at`, `deleted_at`) VALUES (31, 30, 'Aarong Dairy UHT Milk', 'Aarong Dairy UHT (Ultra High Temperature) Milk is long-life fresh milk sterilized at high temperatures without any preservative. It’s directly drinkable that requires no boiling.\r\n\r\nShare and Enjoy!\r\n\r\nCATEGORIES: UHT MILK, LIQUID MILK', '<p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p8846.0.6.0.1.0.1.4.$line-0\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Aarong Dairy UHT (Ultra High Temperature) Milk is long-life fresh milk sterilized at high temperatures without any preservative. It’s directly drinkable that requires no boiling.</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p8846.0.6.0.1.0.1.4.$line-1\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Share and Enjoy!</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p8846.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">CATEGORIES: UHT MILK, LIQUID MILK</p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p8846.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-co