INSERT INTO `product_localizations` (`id`, `product_id`, `name`, `short_description`, `description`, `lang_key`, `created_at`, `updated_at`, `deleted_at`) VALUES (32, 31, 'Danish Condensed Filled Milk', 'Danish sweetened condensed filled milk is scientifically processed under hygienic conditions using skimmed milk powder, refined sugar and edible vegetable fat. It is homogenised and pasteurised to guarantee the quality. Danish sweetened condensed filled milk adds taste and flavor to Tea, Coffee and Milk beverage. You can also use it in Pudding.', '<p><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Danish sweetened condensed filled milk is scientifically processed under hygienic conditions using skimmed milk powder, refined sugar and edible vegetable fat. It is homogenised and pasteurised to guarantee the quality. Danish sweetened condensed filled milk adds taste and flavor to Tea, Coffee and Milk beverage. You can also use it in Pudding.</span></p><p><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\">Danish sweetened condensed filled milk is scientifically processed under hygienic conditions using skimmed milk powder, refined sugar and edible vegetable fat. It is homogenised and pasteurised to guarantee the quality. Danish sweetened condensed filled milk adds taste and flavor to Tea, Coffee and Milk beverage. You can also use it in Pudding.</span><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><br></span><br></p>', 'en', '2023-03-13 04:44:00', '2023-03-13 04:45:20', NULL);
