INSERT INTO `product_localizations` (`id`, `product_id`, `name`, `short_description`, `description`, `lang_key`, `created_at`, `updated_at`, `deleted_at`) VALUES (46, 10, 'कृष्णकमल फल', 'प्रत्येक 1 किलो उत्पाद में अमरूद के 3 पीसी - 4 पीसी होंगे।\r\n\r\nअमरूद हाई-प्रोफाइल पोषक तत्वों से भरपूर एक उष्णकटिबंधीय फल है। थाई अमरूद आमतौर पर सेब की हरी त्वचा के साथ सॉफ्टबॉल के आकार के होते हैं जो ऊबड़-खाबड़ से लेकर चिकने तक हो सकते हैं। गूदा हल्के पीले रंग के बीजों वाला सफेद होता है और गुलाबी प्रकार के अमरूदों की तुलना में अधिक सूखा होता है।', '<p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6024.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">प्रत्येक 1 किलो उत्पाद में अमरूद के 3 पीसी - 4 पीसी होंगे।</font></font></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6024.0.6.0.1.0.1.4.$line-3\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p6024.0.6.0.1.0.1.4.$line-4\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">अमरूद हाई-प्रोफाइल पोषक तत्वों से भ