INSERT INTO `product_localizations` (`id`, `product_id`, `name`, `short_description`, `description`, `lang_key`, `created_at`, `updated_at`, `deleted_at`) VALUES (49, 13, 'अनारोस (अनानास)', 'अनानास दुनिया में सबसे लोकप्रिय उष्णकटिबंधीय फलों में से एक है। ताजे अनानास में कैलोरी कम होती है। बहरहाल, यह कई अद्वितीय स्वास्थ्य को बढ़ावा देने वाले यौगिकों का भंडार है,', '<p><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">अनानास दुनिया में सबसे लोकप्रिय उष्णकटिबंधीय फलों में से एक है। ताजे अनानास में कैलोरी कम होती है। </font><font style=\"vertical-align: inherit;\">बहरहाल, यह कई अद्वितीय स्वास्थ्य को बढ़ावा देने वाले यौगिकों का भंडार है,&nbsp;</font></font></span></p><p><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">अनानास दुनिया में सबसे लोकप्रिय उष्णकटिबंधीय फलों में से एक है। ताजे अनानास में कैलोरी कम होती है। </font><font style=\"vertical-align: inherit;\">बहरहाल, यह कई अद्वितीय स्वास्थ्य को बढ़ावा देने वाले यौगिकों का भंडार है,</font></font></span></p><p><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">अनानास दुनिया में सबसे लोकप्रिय उष्णकटिबंधीय फलों में से एक है। ताजे अनानास में कैलोरी कम होती है। </font><font style=\"vertical-align: inherit;\">बहरहाल, यह कई अद्वितीय स्वास्थ्य को बढ़ावा देने वाले यौगिकों का भंडार है,</font></font></span></p><p><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><br></span><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><br></span><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><br></span><br></p>', 'hi', '2023-03-15 13:28:55', '2023-03-15 13:28:55', NULL);
INSERT INTO `product_localizations` (`id`, `product_id`, `name`, `short_description`, `description`, `lang_key`, `created_at`, `updated_at`, `deleted_at`) VALUES (50, 14, 'गाला सेब ± 50 ग्राम', '8 पीसी -9 पीसी\r\n\r\nहम आपकी संतुष्टि में विश्वास करते हैं और हल्के और मीठे सुखद स्वाद के साथ चलदल से गाला सेब प्राप्त करते हैं। कुल मिलाकर नारंगी रंग इसका पेरेंटेज है: अच्छी गुणवत्ता के साथ गोल्डन स्वादिष्ट और किड्स ऑरेंज रेड। यह न केवल बांग्लादेश में बल्कि दुनिया में भी सबसे पसंदीदा फलों में से एक है।', '<p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p10727.0.6.0.1.0.1.4.$line-0\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">8 पीसी -9 पीसी</font></font></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p10727.0.6.0.1.0.1.4.$line-1\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p10727.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">हम आपकी संतुष्टि में विश्वास करते हैं और हल्के और मीठे सुखद स्वाद के साथ चलदल से गाला सेब प्राप्त करते हैं। </font><font style=\"vertical-align: inherit;\">कुल मिलाकर नारंगी रंग इसका पेरेंटेज है: अच्छी गुणवत्ता के साथ गोल्डन स्वादिष्ट और किड्स ऑरेंज रेड। </font><font style=\"vertical-align: inherit;\">यह न केवल बांग्लादेश में बल्कि दुनिया में भी सबसे पसंदीदा फलों में से एक है।&nbsp;</font></font></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p10727.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><br></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p10727.0.6.0.1.0.1.4.$line-0\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">8 पीसी -9 पीसी</font></font></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p10727.0.6.0.1.0.1.4.$line-1\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p10727.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font sty