INSERT INTO `product_localizations` (`id`, `product_id`, `name`, `short_description`, `description`, `lang_key`, `created_at`, `updated_at`, `deleted_at`) VALUES (65, 29, 'डैन केक क्लासिक ब्राउनीज़', 'डैन केक वेनिला मफिन एक अच्छी गुणवत्ता और स्वादिष्ट भोजन है जिसकी गुणवत्तापूर्ण पैकेजिंग आपको एक अलग स्वाद प्रदान करती है। स्वाद: वेनिला क्रीम भरा हुआ। आप इसे अपने दैनिक नाश्ते में परोस सकते हैं या आप अपने बच्चे को स्कूल टिफिन भोजन के रूप में दे सकते हैं।', '<p><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">डैन केक वेनिला मफिन एक अच्छी गुणवत्ता और स्वादिष्ट भोजन है जिसकी गुणवत्तापूर्ण पैकेजिंग आपको एक अलग स्वाद प्रदान करती है। </font><font style=\"vertical-align: inherit;\">स्वाद: वेनिला क्रीम भरा हुआ। </font><font style=\"vertical-align: inherit;\">आप इसे अपने दैनिक नाश्ते में परोस सकते हैं या आप अपने बच्चे को स्कूल टिफिन भोजन के रूप में दे सकते हैं।&nbsp;</font></font></span></p><p><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">डैन केक वेनिला मफिन एक अच्छी गुणवत्ता और स्वादिष्ट भोजन है जिसकी गुणवत्तापूर्ण पैकेजिंग आपको एक अलग स्वाद प्रदान करती है। </font></font></font><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">स्वाद: वेनिला क्रीम भरा हुआ। </font></font></font><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">आप इसे अपने दैनिक नाश्ते में परोस सकते हैं या आप अपने बच्चे को स्कूल टिफिन भोजन के रूप में दे सकते हैं।</font></font></font></font></span></p><p><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">डैन केक वेनिला मफिन एक अच्छी गुणवत्ता और स्वादिष्ट भोजन है जिसकी गुणवत्तापूर्ण पैकेजिंग आपको एक अलग स्वाद प्रदान करती है। </font></font></font><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">स्वाद: वेनिला क्रीम भरा हुआ। </font></font></font><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">आप इसे अपने दैनिक नाश्ते में परोस सकते हैं या आप अपने बच्चे को स्कूल टिफिन भोजन के रूप में दे सकते हैं।</font></font></font></font></span><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><br></span><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><br></span><br></p>', 'hi', '2023-03-15 13:36:09', '2023-03-15 13:36:09', NULL);
INSERT INTO `product_localizations` (`id`, `product_id`, `name`, `short_description`, `description`, `lang_key`, `created_at`, `updated_at`, `deleted_at`) VALUES (66, 30, 'आरोनग डेयरी यूएचटी दूध', 'एरोंग डेयरी यूएचटी (अल्ट्रा हाई टेम्परेचर) दूध लंबे समय तक चलने वाला ताजा दूध है जिसे बिना किसी प्रिजरवेटिव के उच्च तापमान पर स्टेरलाइज किया जाता है। यह सीधे पीने योग्य है जिसे उबालने की आवश्यकता नहीं है।\r\n\r\nसाझा करें और आनंद लें!\r\n\r\nश्रेणियाँ: UHT दूध, तरल दूध', '<p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p8846.0.6.0.1.0.1.4.$line-0\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">एरोंग डेयरी यूएचटी (अल्ट्रा हाई टेम्परेचर) दूध लंबे समय तक चलने वाला ताजा दूध है जिसे बिना किसी प्रिजरवेटिव के उच्च तापमान पर स्टेरलाइज किया जाता है। </font><font style=\"vertical-align: inherit;\">यह सीधे पीने योग्य है जिसे उबालने की आवश्यकता नहीं है।</font></font></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p8846.0.6.0.1.0.1.4.$line-1\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">साझा करें और आनंद लें!</font></font></p><p data-reactid=\".2e891giyf5c.b.2.0.0.0.0.2.5.1.0:$p8846.0.6.0.1.0.1.4.$line-2\" style=\"box-sizing: border-box; -webkit-tap-highlight-color: transparent; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: &quot