INSERT INTO `product_localizations` (`id`, `product_id`, `name`, `short_description`, `description`, `lang_key`, `created_at`, `updated_at`, `deleted_at`) VALUES (67, 31, 'डेनिश संघनित भरा दूध', 'स्किम्ड मिल्क पाउडर, रिफाइंड चीनी और खाद्य वनस्पति वसा का उपयोग करके डेनिश मीठा गाढ़ा दूध वैज्ञानिक रूप से स्वच्छ परिस्थितियों में संसाधित किया जाता है। गुणवत्ता की गारंटी के लिए इसे समरूप और पास्चुरीकृत किया जाता है। डेनिश मीठा गाढ़ा दूध चाय, कॉफी और दूध पेय में स्वाद और स्वाद जोड़ता है। आप इसका इस्तेमाल पुडिंग में भी कर सकते हैं.', '<p><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">स्किम्ड मिल्क पाउडर, रिफाइंड चीनी और खाद्य वनस्पति वसा का उपयोग करके डेनिश मीठा गाढ़ा दूध वैज्ञानिक रूप से स्वच्छ परिस्थितियों में संसाधित किया जाता है। </font><font style=\"vertical-align: inherit;\">गुणवत्ता की गारंटी के लिए इसे समरूप और पास्चुरीकृत किया जाता है। </font><font style=\"vertical-align: inherit;\">डेनिश मीठा गाढ़ा दूध चाय, कॉफी और दूध पेय में स्वाद और स्वाद जोड़ता है। </font><font style=\"vertical-align: inherit;\">आप इसका इस्तेमाल पुडिंग में भी कर सकते हैं.&nbsp;</font></font></span></p><p><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><font style=\"vertical-align: inherit;\"><font style=\"vertical-align: inherit;\">स्किम्ड मिल्क पाउडर, रिफाइंड चीनी और खाद्य वनस्पति वसा का उपयोग करके डेनिश मीठा गाढ़ा दूध वैज्ञानिक रूप से स्वच्छ परिस्थितियों में संसाधित किया जाता है। </font><font style=\"vertical-align: inherit;\">गुणवत्ता की गारंटी के लिए इसे समरूप और पास्चुरीकृत किया जाता है। </font><font style=\"vertical-align: inherit;\">डेनिश मीठा गाढ़ा दूध चाय, कॉफी और दूध पेय में स्वाद और स्वाद जोड़ता है। </font><font style=\"vertical-align: inherit;\">आप इसका इस्तेमाल पुडिंग में भी कर सकते हैं.</font></font></span><span style=\"color: rgb(51, 51, 51); font-family: &quot;segoe ui&quot;, Helvetica, &quot;droid sans&quot;, Arial, &quot;lucida grande&quot;, tahoma, verdana, arial, sans-serif;\"><br></span><br></p>', 'hi', '2023-03-15 13:36:43', '2023-03-15 13:36:43', NULL);
